        ["Tank"] = ["Tanque", "Tank", "Tank", "Đỡ đòn"],
        ["A new version is available: {0}. Click here to install it."] = ["Há uma nova versão disponível: {0}. Clique aqui para instalá-la.", "Une nouvelle version est disponible : {0}. Cliquez ici pour l'installer.", "Eine neue Version ist verfügbar: {0}. Klicke hier, um sie zu installieren.", "Đã có phiên bản mới: {0}. Bấm vào đây để cài đặt."],
        ["Couldn't load the game data:\n{0}"] = ["Não foi possível carregar os dados do jogo:\n{0}", "Impossible de charger les données du jeu :\n{0}", "Die Spieldaten konnten nicht geladen werden:\n{0}", "Không tải được dữ liệu trò chơi:\n{0}"],
        ["Windows has no OCR language installed.\nAdd Spanish or English in Settings > Time & language > Language."] = ["O Windows não tem nenhum idioma de OCR instalado.\nAdicione espanhol ou inglês em Configurações > Hora e idioma > Idioma.", "Windows n'a aucune langue d'OCR installée.\nAjoutez l'espagnol ou l'anglais dans Paramètres > Heure et langue > Langue.", "Windows hat keine OCR-Sprache installiert.\nFüge Spanisch oder Englisch unter Einstellungen > Zeit und Sprache > Sprache hinzu.", "Windows chưa cài ngôn ngữ OCR nào.\nHãy thêm tiếng Tây Ban Nha hoặc tiếng Anh trong Cài đặt > Thời gian và ngôn ngữ > Ngôn ngữ."],
        ["{0} games{1}"] = ["{0} partidas{1}", "{0} parties{1}", "{0} Spiele{1}", "{0} trận{1}"],
