        ["Victory with {0} ({1}/{2}/{3}). Click to see the summary."] = ["Vitória com {0} ({1}/{2}/{3}). Clique para ver o resumo.", "Victoire avec {0} ({1}/{2}/{3}). Cliquez pour voir le résumé.", "Sieg mit {0} ({1}/{2}/{3}). Klicke, um die Zusammenfassung zu sehen.", "Thắng với {0} ({1}/{2}/{3}). Bấm để xem tóm tắt."],
        ["Defeat with {0} ({1}/{2}/{3}). Click to see the summary."] = ["Derrota com {0} ({1}/{2}/{3}). Clique para ver o resumo.", "Défaite avec {0} ({1}/{2}/{3}). Cliquez pour voir le résumé.", "Niederlage mit {0} ({1}/{2}/{3}). Klicke, um die Zusammenfassung zu sehen.", "Thua với {0} ({1}/{2}/{3}). Bấm để xem tóm tắt."],
        ["Install version {0}"] = ["Instalar a versão {0}", "Installer la version {0}", "Version {0} installieren", "Cài phiên bản {0}"],
        ["Microsoft Edge WebView2 is missing. Install it from Microsoft's website and open the app again."] = ["Falta o Microsoft Edge WebView2. Instale-o pelo site da Microsoft e abra o app de novo.", "Microsoft Edge WebView2 est manquant. Installez-le depuis le site de Microsoft et rouvrez l'app.", "Microsoft Edge WebView2 fehlt. Installiere es von der Microsoft-Website und öffne die App erneut.", "Thiếu Microsoft Edge WebView2. Hãy cài từ trang web của Microsoft rồi mở lại ứng dụng."],
