        ["{0} games on your champion"] = ["{0} partidas com seu campeão", "{0} parties avec votre champion", "{0} Spiele mit deinem Champion", "{0} trận với tướng của bạn"],
        ["no games on your champion yet"] = ["ainda sem partidas com seu campeão", "pas encore de parties avec votre champion", "noch keine Spiele mit deinem Champion", "chưa có trận nào với tướng của bạn"],
        ["Boosts: "] = ["Potencializa: ", "Renforce : ", "Verstärkt: ", "Tăng: "],
