        ["You can afford it!"] = ["Dá para comprar!", "Vous pouvez l'acheter !", "Du kannst es dir leisten!", "Bạn đủ tiền mua!"],
        ["{0} gold to go (costs {1})"] = ["Faltam {0} de ouro (custa {1})", "Encore {0} or (coûte {1})", "Noch {0} Gold (kostet {1})", "Còn thiếu {0} vàng (giá {1})"],
        ["SELL AND SWAP"] = ["VENDER E TROCAR", "VENDRE ET ÉCHANGER", "VERKAUFEN UND TAUSCHEN", "BÁN VÀ ĐỔI"],
