        ["ITEMS"] = ["ITENS", "OBJETS", "ITEMS", "TRANG BỊ"],
        ["Inventory full: no room for more items."] = ["Inventário cheio: não cabem mais itens.", "Inventaire plein : plus de place pour d'autres objets.", "Inventar voll: kein Platz für weitere Items.", "Túi đồ đầy: không còn chỗ cho món khác."],
        ["Not enough data yet."] = ["Ainda não há dados suficientes.", "Pas encore assez de données.", "Noch nicht genug Daten.", "Chưa đủ dữ liệu."],
        ["YOUR AUGMENTS"] = ["SEUS APRIMORAMENTOS", "VOS OPTIMISATIONS", "DEINE AUGMENTIERUNGEN", "NÂNG CẤP CỦA BẠN"],
        ["SKILLS"] = ["HABILIDADES", "COMPÉTENCES", "FÄHIGKEITEN", "KỸ NĂNG"],
        ["Max {0}  ·  {1} in {2} games"] = ["Maximize {0}  ·  {1:P0} em {2} partidas", "Montez {0}  ·  {1:P0} sur {2} parties", "Maximiere {0}  ·  {1:P0} in {2} Spielen", "Nâng tối đa {0}  ·  {1:P0} trong {2} trận"],
        ["RECOMMENDED FULL BUILD"] = ["BUILD COMPLETA RECOMENDADA", "BUILD COMPLÈTE RECOMMANDÉE", "EMPFOHLENER KOMPLETTER BUILD", "BUILD ĐẦY ĐỦ ĐỀ XUẤT"],
        ["You already have the recommended build."] = ["Você já tem a build recomendada.", "Vous avez déjà la build recommandée.", "Du hast schon den empfohlenen Build.", "Bạn đã có build đề xuất."],
        ["CHAMPION SELECT"] = ["SELEÇÃO DE CAMPEÕES", "SÉLECTION DES CHAMPIONS", "CHAMPIONAUSWAHL", "CHỌN TƯỚNG"],
        ["Mayhem win rate (all players) · yours below"] = ["% de vitórias na Desordem (todos) · o seu abaixo", "% de victoires en ARAM du chaos (tous) · le vôtre en dessous", "Siegrate in ARAM: Chaos (alle) · deine darunter", "Tỉ lệ thắng Hỗn Loạn (mọi người) · của bạn ở dưới"],
        ["Win rate in your Mayhem games"] = ["% de vitórias nas suas partidas de Desordem", "% de victoires dans vos parties du chaos", "Siegrate in deinen Chaos-Spielen", "Tỉ lệ thắng trong các trận Hỗn Loạn của bạn"],
        ["  (yours)"] = ["  (o seu)", "  (le vôtre)", "  (deiner)", "  (của bạn)"],
        ["  ★ best pick"] = ["  ★ melhor escolha", "  ★ meilleur choix", "  ★ beste Wahl", "  ★ lựa chọn tốt nhất"],
        ["{0} win rate · {1} games"] = ["{0:P1} de vitórias · {1:N0} partidas", "{0:P1} de victoires · {1:N0} parties", "{0:P1} Siegrate · {1:N0} Spiele", "{0:P1} tỉ lệ thắng · {1:N0} trận"],
        ["{0}{1} win rate · {2} games"] = ["{0}{1:P0} de vitórias · {2} partidas", "{0}{1:P0} de victoires · {2} parties", "{0}{1:P0} Siegrate · {2} Spiele", "{0}{1:P0} tỉ lệ thắng · {2} trận"],
        ["You: "] = ["Você: ", "Vous : ", "Du: ", "Bạn: "],
        ["no games of yours yet"] = ["ainda sem partidas suas", "pas encore de parties à vous", "noch keine Spiele von dir", "bạn chưa có trận nào"],
        ["Little data yet: play more games and this gets more reliable."] = ["Ainda há poucos dados: jogue mais partidas e isto fica mais confiável.", "Encore peu de données : jouez plus de parties et ce sera plus fiable.", "Noch wenige Daten: spiel mehr Spiele, dann wird das zuverlässiger.", "Còn ít dữ liệu: chơi thêm trận thì thông tin này sẽ đáng tin hơn."],
        ["The new version has no SHA-256 fingerprint."] = ["A nova versão não tem impressão digital SHA-256.", "La nouvelle version n'a pas d'empreinte SHA-256.", "Die neue Version hat keinen SHA-256-Fingerabdruck.", "Phiên bản mới không có dấu vân tay SHA-256."],
        ["The downloaded installer doesn't match the one on GitHub: it won't be installed."] = ["O instalador baixado não coincide com o do GitHub: não será instalado.", "L'installateur téléchargé ne correspond pas à celui de GitHub : il ne sera pas installé.", "Das heruntergeladene Installationsprogramm stimmt nicht mit dem auf GitHub überein: es wird nicht installiert.", "Bộ cài đã tải không khớp với bản trên GitHub: sẽ không được cài."],
        ["Augments come at the start (level 3) and when you reach levels 7, 11 and 15. Each of the three cards can be rerolled once, for another of the same rarity: up to 6 options per pick."] = ["Os aprimoramentos vêm no começo (nível 3) e ao chegar aos níveis 7, 11 e 15. Cada uma das três cartas pode ser trocada uma vez, por outra da mesma raridade: até 6 opções em cada escolha.", "Les optimisations arrivent au début (niveau 3) puis aux niveaux 7, 11 et 15. Chacune des trois cartes peut être relancée une fois, contre une autre de même rareté : jusqu'à 6 options par choix.", "Augmentierungen gibt es zu Beginn (Stufe 3) und beim Erreichen der Stufen 7, 11 und 15. Jede der drei Karten kann einmal neu gewürfelt werden, gegen eine andere derselben Seltenheit: bis zu 6 Optionen pro Wahl.", "Nâng Cấp xuất hiện lúc đầu trận (cấp 3) và khi đạt cấp 7, 11 và 15. Mỗi thẻ trong ba thẻ có thể đổi một lần, lấy thẻ khác cùng độ hiếm: tối đa 6 lựa chọn mỗi lượt."],
        ["Cards only show up when you can shop (dead, or at base after respawning). If you hide them to look at the map, the shop stays closed until you pick."] = ["As cartas só aparecem quando você pode comprar (morto ou na base ao renascer). Se escondê-las para olhar o mapa, a loja não abre até você escolher.", "Les cartes n'apparaissent que quand vous pouvez acheter (mort, ou à la base après réapparition). Si vous les cachez pour regarder la carte, la boutique reste fermée jusqu'à votre choix.", "Die Karten erscheinen nur, wenn du einkaufen kannst (tot oder nach dem Respawn in der Basis). Wenn du sie ausblendest, um auf die Karte zu schauen, bleibt der Shop zu, bis du wählst.", "Thẻ chỉ hiện khi bạn có thể mua đồ (khi chết hoặc ở nhà chính lúc hồi sinh). Nếu bạn ẩn thẻ để xem bản đồ, cửa hàng sẽ không mở cho đến khi bạn chọn."],
        ["In Mayhem, crit above 100% isn't fully wasted: each extra 1% gives 0.45 attack damage or 0.75 ability power. Still, another crit item is worth far less than a damage item."] = ["Na Desordem, o crítico acima de 100% não se perde totalmente: cada 1% a mais dá 0,45 de dano de ataque ou 0,75 de poder de habilidade. Mesmo assim, outro item de crítico rende muito menos que um de dano.", "En ARAM du chaos, le critique au-delà de 100 % n'est pas totalement perdu : chaque 1 % en plus donne 0,45 de dégâts d'attaque ou 0,75 de puissance. Malgré tout, un autre objet critique vaut bien moins qu'un objet de dégâts.", "In ARAM: Chaos geht Krit über 100 % nicht ganz verloren: jedes zusätzliche 1 % gibt 0,45 Angriffsschaden oder 0,75 Fähigkeitsstärke. Trotzdem bringt ein weiteres Krit-Item viel weniger als ein Schadens-Item.", "Ở Hỗn Loạn, chí mạng trên 100% không mất hẳn: mỗi 1% thừa cho 0,45 sức mạnh công kích hoặc 0,75 sức mạnh phép thuật. Dù vậy, thêm một món chí mạng vẫn kém xa một món sát thương."],
        ["Attack speed goes up to 5.0 (not 2.5 like on the Rift): fast-attack and on-hit builds have more room to grow."] = ["A velocidade de ataque vai até 5,0 (não 2,5 como na Summoner's Rift): builds de ataques rápidos e efeitos ao atingir têm mais espaço.", "La vitesse d'attaque monte jusqu'à 5,0 (et non 2,5 comme sur la Faille) : les builds d'attaques rapides et d'effets à l'impact ont plus de marge.", "Das Angriffstempo geht bis 5,0 (nicht 2,5 wie auf der Kluft): Builds mit schnellen Angriffen und Treffereffekten haben mehr Luft nach oben.", "Tốc độ đánh tối đa là 5,0 (không phải 2,5 như ở Summoner's Rift): build đánh nhanh và hiệu ứng trên đòn đánh có nhiều đất diễn hơn."],
        ["Combo Breaker: if you're immobilized 5 of the last 7 seconds, you're cleansed and get 3 seconds of CC immunity. Against heavy-CC teams, hold on: it comes on its own."] = ["Quebra-combo: se você ficar imobilizado 5 dos últimos 7 segundos, é purificado e ganha 3 segundos imune a controle. Contra times com muito controle, aguente: ele vem sozinho.", "Brise-combo : si vous êtes immobilisé 5 des 7 dernières secondes, vous êtes purifié et immunisé aux contrôles pendant 3 secondes. Contre les équipes à gros contrôle, tenez bon : ça vient tout seul.", "Kombobrecher: Bist du 5 der letzten 7 Sekunden bewegungsunfähig, wirst du gereinigt und bist 3 Sekunden immun gegen Kontrolle. Gegen Teams mit viel Kontrolle: durchhalten, es kommt von selbst.", "Phá combo: nếu bạn bị khống chế 5 trong 7 giây gần nhất, bạn được giải hiệu ứng và miễn khống chế 3 giây. Gặp đội nhiều khống chế, hãy cố trụ: nó tự đến."],
        ["Health relics restore 22% of your missing health and mana. Taking one before a fight beats going in at half health."] = ["As relíquias de vida restauram 22% da vida e da mana que faltam. Pegar uma antes da luta vale mais que entrar com meia vida.", "Les reliques de soin rendent 22 % des PV et du mana manquants. En prendre une avant un combat vaut mieux qu'y aller à mi-vie.", "Lebensrelikte stellen 22 % des fehlenden Lebens und Manas wieder her. Eines vor einem Kampf zu nehmen ist besser, als mit halbem Leben reinzugehen.", "Bùa hồi máu hồi 22% máu và năng lượng đã mất. Lấy một bùa trước giao tranh tốt hơn vào trận khi còn nửa máu."],
        ["The Nexus has 3,000 health (5,500 in normal ARAM): once an inhibitor falls, one won fight can end the game."] = ["O nexus tem 3.000 de vida (no ARAM normal, 5.500): quando um inibidor cai, uma luta vencida pode acabar a partida.", "Le Nexus a 3 000 PV (5 500 en ARAM normal) : quand un inhibiteur tombe, un combat gagné peut finir la partie.", "Der Nexus hat 3.000 Leben (im normalen ARAM 5.500): fällt ein Inhibitor, kann ein gewonnener Kampf das Spiel beenden.", "Nhà chính có 3.000 máu (ARAM thường là 5.500): khi một nhà lính bị phá, một pha giao tranh thắng có thể kết thúc trận."],
        ["From level 9 you can spend spare gold on “Stat Bonus” (750 gold): it's a Stat Anvil and you also get a free Cappa Juice. The app scores its shards when they show up."] = ["A partir do nível 9 você pode gastar o ouro que sobra em “Estatística adicional” (750 de ouro): é uma bigorna de estatísticas e você ainda ganha um Suquinho de Cappa. O app dá nota aos fragmentos quando aparecem.", "Dès le niveau 9, vous pouvez dépenser l'or en trop dans « Bonus de stats » (750 or) : c'est une enclume de stats et vous recevez aussi un Jus de Cappa. L'app note ses fragments quand ils apparaissent.", "Ab Stufe 9 kannst du übriges Gold für „Statusbonus“ ausgeben (750 Gold): das ist ein Status-Amboss und du bekommst dazu einen Cappa-Saft. Die App bewertet die Splitter, wenn sie erscheinen.", "Từ cấp 9 bạn có thể tiêu vàng thừa vào “Chỉ số bổ sung” (750 vàng): đó là một đe chỉ số và bạn còn được tặng một Nước Cappa. Ứng dụng sẽ chấm điểm các mảnh khi chúng xuất hiện."],
        ["There are no runes and no Exhaust: some keystones come as augments, so read each card's description."] = ["Não há runas nem Exaustão: algumas runas principais vêm como aprimoramentos, então leia bem a descrição de cada carta.", "Il n'y a ni runes ni Fatigue : certaines clés de voûte arrivent sous forme d'optimisations, lisez donc bien la description de chaque carte.", "Es gibt keine Runen und keine Erschöpfung: manche Schlüsselsteine kommen als Augmentierungen, also lies die Beschreibung jeder Karte genau.", "Không có bảng ngọc và không có Kiệt Sức: một số ngọc chính xuất hiện dưới dạng Nâng Cấp, nên hãy đọc kỹ mô tả từng thẻ."],
        ["Almost nobody opens with boots in Mayhem (0-18% depending on the champion, per aramkit) and 26-38% never buy them: your item first, then boots."] = ["Quase ninguém começa pelas botas na Desordem (no aramkit, 0-18% conforme o campeão) e 26-38% nunca as compram: primeiro seu item, depois as botas.", "Presque personne ne commence par les bottes en ARAM du chaos (0-18 % selon le champion, d'après aramkit) et 26-38 % ne les achètent jamais : votre objet d'abord, puis les bottes.", "In ARAM: Chaos startet fast niemand mit Stiefeln (laut aramkit 0-18 % je nach Champion) und 26-38 % kaufen nie welche: zuerst dein Item, dann die Stiefel.", "Ở Hỗn Loạn gần như không ai mua giày đầu tiên (0-18% tùy tướng, theo aramkit) và 26-38% không bao giờ mua: món của bạn trước, rồi mới đến giày."],
        ["When you die the panel opens on “Buy” by itself: you have a few seconds of shop, and the first thing you see is what to buy and which part you can afford."] = ["Ao morrer, o painel abre sozinho em “Compras”: você tem poucos segundos de loja, e a primeira coisa que vê é o que comprar e que peça já dá para pegar.", "À votre mort, le panneau s'ouvre tout seul sur « Achats » : vous avez quelques secondes de boutique, et la première chose que vous voyez est quoi acheter et quelle pièce vous pouvez déjà vous offrir.", "Wenn du stirbst, öffnet sich das Panel von selbst auf „Kaufen“: du hast nur wenige Sekunden im Shop, und als Erstes siehst du, was du kaufen sollst und welches Teil du dir schon leisten kannst.", "Khi bạn chết, bảng tự mở thẻ “Mua đồ”: bạn chỉ có vài giây ở cửa hàng, và điều đầu tiên bạn thấy là nên mua gì và món thành phần nào đã đủ tiền."],
        ["In the panel's “BUILD TYPE” you can lock a build (on-hit, AP, tank…): every purchase follows it for the rest of the game. Tap it again to let the app choose."] = ["Em “TIPO DE BUILD” do painel você pode fixar uma build (on-hit, AP, tanque…): todas as compras a seguem pelo resto da partida. Toque de novo para o app voltar a escolher.", "Dans « TYPE DE BUILD » du panneau, vous pouvez fixer une build (à l'impact, AP, tank…) : tous les achats la suivent pour le reste de la partie. Touchez-la à nouveau pour laisser l'app choisir.", "Unter „BUILD-TYP“ im Panel kannst du einen Build festlegen (On-Hit, AP, Tank…): alle Käufe folgen ihm für den Rest des Spiels. Tippe erneut, damit die App wieder wählt.", "Trong “KIỂU BUILD” của bảng bạn có thể khóa một build (hiệu ứng đòn đánh, AP, đỡ đòn…): mọi món mua sẽ theo build đó đến hết trận. Bấm lần nữa để ứng dụng tự chọn lại."],
        ["“Keep building…” in the panel: the app won't tell you to switch away from an item you're already building."] = ["“Ficar com meu item” no painel: o app não vai mandar você trocar o item que já está fazendo.", "« Je garde mon objet » dans le panneau : l'app ne vous dira pas d'abandonner l'objet que vous êtes en train de faire.", "„Ich behalte mein Item“ im Panel: die App sagt dir nicht, dass du das Item wechseln sollst, das du gerade baust.", "“Giữ món của tôi” trong bảng: ứng dụng sẽ không bảo bạn bỏ món đang ghép dở."],
        ["The panel's “Adapt” tab tells you how much magic and physical damage the enemy team deals and what to buy against it (resists, grievous wounds, anti-shield…)."] = ["A aba “Adaptar” do painel diz quanto dano mágico e físico o time inimigo causa e o que comprar contra ele (resistências, feridas dolorosas, antiescudo…).", "L'onglet « Adapter » du panneau vous dit combien de dégâts magiques et physiques fait l'équipe ennemie et quoi acheter contre elle (résistances, blessures graves, anti-bouclier…).", "Der Tab „Anpassen“ im Panel zeigt, wie viel magischen und physischen Schaden das gegnerische Team macht und was du dagegen kaufen solltest (Resistenzen, Klaffende Wunden, Anti-Schild…).", "Thẻ “Thích ứng” của bảng cho biết đội địch gây bao nhiêu sát thương phép và vật lý và nên mua gì để chống (kháng, vết thương sâu, phá lá chắn…)."],
        ["Is the panel in the way? Drag it by the top bar, resize it from the bottom-left corner, or press ⊟ to keep just “Buy now”."] = ["O painel atrapalha? Arraste-o pela barra de cima, mude o tamanho pelo canto de baixo à esquerda ou aperte ⊟ para deixar só “Compre agora”.", "Le panneau vous gêne ? Déplacez-le par la barre du haut, redimensionnez-le par le coin en bas à gauche ou appuyez sur ⊟ pour ne garder que « Achetez maintenant ».", "Stört das Panel? Zieh es an der oberen Leiste, ändere die Größe an der unteren linken Ecke oder drück ⊟, um nur „Jetzt kaufen“ zu behalten.", "Bảng che mất thứ gì? Kéo nó bằng thanh phía trên, đổi kích thước ở góc dưới bên trái, hoặc bấm ⊟ để chỉ giữ “Mua ngay”."],
        ["In champion select, the panel ranks your champion and the bench by their Mayhem win rate: “Take” swaps it in one click."] = ["Na seleção de campeões, o painel ordena seu campeão e os do banco pelas vitórias na Desordem: “Pegar” troca com um clique.", "En sélection des champions, le panneau classe votre champion et ceux du banc selon leurs victoires en ARAM du chaos : « Prendre » l'échange en un clic.", "In der Championauswahl sortiert das Panel deinen Champion und die der Bank nach ihrer Siegrate in ARAM: Chaos: „Nehmen“ tauscht ihn mit einem Klick.", "Khi chọn tướng, bảng xếp tướng của bạn và các tướng ở hàng chờ theo tỉ lệ thắng Hỗn Loạn: “Lấy” đổi tướng chỉ với một cú bấm."],
        ["In champion select the app puts its build in the in-game shop (recommended builds tab), with what to change against heavy magic or physical damage."] = ["Na seleção de campeões o app coloca a build dele na loja do jogo (aba de builds recomendadas), com o que trocar contra muito dano mágico ou físico.", "En sélection des champions, l'app place sa build dans la boutique du jeu (onglet des builds recommandées), avec quoi changer contre beaucoup de dégâts magiques ou physiques.", "In der Championauswahl legt die App ihren Build in den Shop des Spiels (Tab mit empfohlenen Builds), samt Alternativen gegen viel magischen oder physischen Schaden.", "Khi chọn tướng, ứng dụng đưa build của nó vào cửa hàng trong trận (thẻ build đề xuất), kèm món nên đổi khi gặp nhiều sát thương phép hoặc vật lý."],
        ["Cards are read from the screen: in fullscreen nothing can be seen. Use borderless (the champion select panel switches it with one button)."] = ["As cartas são lidas da tela: com o jogo em tela cheia não se vê nada. Use “sem bordas” (o painel da seleção de campeões muda isso com um botão).", "Les cartes sont lues à l'écran : en plein écran, rien n'est visible. Utilisez le mode « sans bordure » (le panneau de sélection des champions le change en un bouton).", "Die Karten werden vom Bildschirm gelesen: im Vollbild ist nichts zu sehen. Nutze „Randlos“ (das Panel der Championauswahl stellt es mit einem Knopf um).", "Thẻ được đọc từ màn hình: ở chế độ toàn màn hình thì không thấy gì. Hãy dùng chế độ không viền (bảng chọn tướng có nút đổi nhanh)."],
        ["“Games” has a summary of each game: your place among the 10, your augment scores and an image to paste in Discord or WhatsApp."] = ["Em “Partidas” você tem o resumo de cada partida: sua posição entre os 10, a nota dos seus aprimoramentos e uma imagem para colar no Discord ou no WhatsApp.", "Dans « Parties », vous avez le résumé de chaque partie : votre place parmi les 10, la note de vos optimisations et une image à coller dans Discord ou WhatsApp.", "Unter „Spiele“ findest du eine Zusammenfassung jedes Spiels: deinen Platz unter den 10, die Bewertung deiner Augmentierungen und ein Bild zum Einfügen in Discord oder WhatsApp.", "Trong “Trận đấu” có tóm tắt từng trận: thứ hạng của bạn trong 10 người, điểm Nâng Cấp và một hình ảnh để dán vào Discord hoặc WhatsApp."],
        ["Something odd or an idea? Tell us in “Suggestions”: the app's creator reads it and uses it to decide what to fix first."] = ["Algo estranho ou uma ideia? Conte em “Sugestões”: o criador do app lê e usa isso para decidir o que arrumar primeiro.", "Quelque chose d'étrange ou une idée ? Dites-le dans « Suggestions » : le créateur de l'app le lit et s'en sert pour décider quoi corriger en premier.", "Etwas Seltsames oder eine Idee? Schreib es unter „Vorschläge“: der Entwickler der App liest es und entscheidet damit, was zuerst behoben wird.", "Có gì lạ hoặc có ý tưởng? Hãy gửi trong “Góp ý”: người tạo ứng dụng sẽ đọc và dùng nó để quyết định sửa gì trước."],
        ["Penetration"] = ["Penetração", "Pénétration", "Durchdringung", "Xuyên giáp"],
        ["Armor"] = ["Armadura", "Armure", "Rüstung", "Giáp"],
        ["Magic resist"] = ["Resist. mágica", "Rés. magique", "Magieresistenz", "Kháng phép"],
        ["Tenacity"] = ["Tenacidade", "Ténacité", "Zähigkeit", "Kháng hiệu ứng"],
        ["Health"] = ["Vida", "PV", "Leben", "Máu"],
        ["Ability haste"] = ["Aceleração", "Accélération", "Fähigkeitstempo", "Điểm hồi kỹ năng"],
        ["Mobility"] = ["Mobilidade", "Mobilité", "Mobilität", "Cơ động"],
    };
}
